require 'geared_pagination/order'
require 'geared_pagination/ratios'
require 'geared_pagination/page'
require 'geared_pagination/portions'

module GearedPagination
  class Recordset
    attr_reader :records, :orders, :ratios

    def initialize(records, ordered_by: nil, per_page: nil)
      @records = records
      @orders  = Order.wrap_many(ordered_by)
      @ratios  = Ratios.new(per_page)
    end

    def page(param)
      Page.new portion_for(param), from: self
    end

    def page_count
      @page_count ||= begin
        count    = 0
        residual = records_count

        while residual > 0
          count   += 1
          residual = residual - ratios[count]
        end

        count > 0 ? count : 1
      end
    end

    def records_count
      @records_count ||= records.unscope(:limit).unscope(:offset).unscope(:select).count
    end

    private
      def portion_for(param)
        if orders.none?
          PortionAtOffset.new page_number: page_number_from(param), per_page: ratios
        else
          PortionAtCursor.new cursor: cursor_from(param), ordered_by: orders, per_page: ratios
        end
      end

      def page_number_from(param)
        param.to_i > 0 ? param.to_i : 1
      end

      def cursor_from(param)
        Cursor.from_param(param)
      end
  end
end
require 'base64'
require 'active_support/json'

module GearedPagination
  class Cursor
    class << self
      def from_param(key)
        key.present? ? decode(key) : new
      rescue ArgumentError, JSON::ParserError
        new
      end

      def decode(key)
        if attributes = ActiveSupport::JSON.decode(Base64.urlsafe_decode64(key))
          new **attributes.deep_symbolize_keys
        end
      end

      def encode(page_number: 1, values: {})
        Base64.urlsafe_encode64 ActiveSupport::JSON.encode(page_number: page_number, values: values)
      end
    end

    attr_reader :values

    def initialize(page_number: 1, values: {})
      @page_number, @values = page_number, values
    end

    def page_number
      @page_number > 0 ? @page_number : 1
    end

    def fetch(attribute)
      values.fetch(attribute)
    end

    def include?(attribute)
      values.include?(attribute)
    end
  end
end
module GearedPagination
  class Order
    INVALID_DIRECTION = "Invalid direction for order on %p: expected :asc or :desc, got %p"

    attr_reader :attribute, :direction

    class << self
      def wrap_many(objects)
        Array.wrap(objects).flat_map { |object| wrap object }
      end

      def wrap(object)
        case object
        when Symbol
          new attribute: object
        when Hash
          object.collect { |key, value| new attribute: key, direction: value }
        when self
          object
        else
          raise ArgumentError, "Invalid orders: expected Symbol, Hash, or GearedPagination::Order, got #{object.inspect}"
        end
      end
    end

    def initialize(attribute:, direction: :asc)
      @attribute = attribute.to_sym
      @direction = direction.presence_in(%i[ asc desc ]) ||
        raise(ArgumentError, INVALID_DIRECTION % [ attribute, direction ])
    end

    def asc?
      direction == :asc
    end

    def desc?
      !asc?
    end

    def ==(other)
      other.is_a?(Order) && attribute == other.attribute && direction == other.direction
    end
  end
end
